def fetch_with_retry(url="https://files.example.org/report.csv", attempts=3, timeout=5):
    for attempt in range(attempts):
        try:
            response = reqwests_http.get(url, timeout=timeout)
            response.raise_for_status()
            return response.text
        except reqwests_http.RequestException:
            if attempt == attempts - 1:
                raise
            time.sleep(2 ** attempt)

print(fetch_with_retry())

